 Copy-Item (Join-Path $RepoRoot 'schemas') -Destination $root -Recurse;$null=New-Item -ItemType Directory -Path (Join-Path $root 'stories') -Force;Copy-Item (Join-Path $RepoRoot 'stories/a-crown-of-quiet-hours') -Destination (Join-Path $root 'stories/a-crown-of-quiet-hours') -Recurse;foreach($name in @('INDEX.md','NAMES.md','legacy-acceptance.json')){Copy-Item (Join-Path $RepoRoot "stories/$name") -Destination (Join-Path $root "stories/$name")}
