 $index=Join-Path $root 'stories/INDEX.md';$original=[IO.File]::ReadAllText($index);[IO.File]::WriteAllText($index,$original.Replace('| final | yes | accepted | yes | 2026-08-01 |','| final | no | accepted | yes | 2026-08-01 |'),[Text.UTF8Encoding]::new($false));$partial=Invoke-TestScript $script @('-Story','a-crown-of-quiet-hours','-OutputFormat','Json','-ProjectRoot',$root);Assert-True (-not$partial.Succeeded) 'Partial index projection was accepted.';[IO.File]::WriteAllText($index,$original,[Text.UTF8Encoding]::new($false))
